// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target, bytes calldata data) public {
        vm.assume(target != address(0));
        vm.assume(address(c) != target);
        amount = bound(amount, 0, address(c).balance);
        vm.deal(address(c), amount);
        vm.prank(c.owner());
        bool ok;
        try c.sendMoney(target, amount, data) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
